// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 _value, bytes memory _data) public {
        vm.assume(_value <= type(uint256).max - 1);
        vm.deal(address(c), _value + 1);

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney with a revert catcher to avoid reverts
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.sendMoney.selector, address(0xdead), _value, _data)
        );

        uint256 balanceAfter = address(c).balance;

        // The rule: the reference always sends exactly _value (or less if balance < _value)
        if (success) {
            if (balanceBefore >= _value) {
                assertTrue(balanceAfter == balanceBefore - _value, "balance after should be before minus value");
            } else {
                assertTrue(balanceAfter == 0, "balance after should be zero if not enough funds");
            }
        }
    }
}

